module ram_8x6(
  input  [2:0] R0_addr,
  input        R0_en,
               R0_clk,
  output [5:0] R0_data,
  input  [2:0] W0_addr,
  input        W0_en,
               W0_clk,
  input  [5:0] W0_data
);

  reg [5:0] Memory[0:7];
  always @(posedge W0_clk) begin
    if (W0_en & 1'h1)
