  end // always @(posedge)
  assign R0_data = R0_en ? Memory[R0_addr] : 6'bx;
endmodule

module Queue8_Meta(
  input        clock,
               reset,
  output       io_enq_ready,
  input        io_enq_valid,
  input  [2:0] io_enq_bits_context,
  input        io_enq_bits_last,
               io_enq_bits_finish,
               io_enq_bits_emit,
               io_deq_ready,
  output       io_deq_valid,
  output [2:0] io_deq_bits_context,
  output       io_deq_bits_last,
               io_deq_bits_finish,
               io_deq_bits_emit
);

  wire       io_enq_ready_0;
  wire [5:0] _ram_ext_R0_data;
  reg  [2:0] enq_ptr_value;
  reg  [2:0] deq_ptr_value;
  reg        maybe_full;
  wire       ptr_match = enq_ptr_value == deq_ptr_value;
  wire       empty = ptr_match & ~maybe_full;
  wire       do_enq = io_enq_ready_0 & io_enq_valid;
  assign io_enq_ready_0 = io_deq_ready | ~(ptr_match & maybe_full);
  always @(posedge clock) begin
    if (reset) begin
      enq_ptr_value <= 3'h0;
      deq_ptr_value <= 3'h0;
      maybe_full <= 1'h0;
    end
    else begin
      automatic logic do_deq = io_deq_ready & ~empty;
      if (do_enq)
        enq_ptr_value <= enq_ptr_value + 3'h1;
      if (do_deq)
        deq_ptr_value <= deq_ptr_value + 3'h1;
      if (~(do_enq == do_deq))
        maybe_full <= do_enq;
    end
  end // always @(posedge)
  ram_8x6 ram_ext (
    .R0_addr (deq_ptr_value),
    .R0_en   (1'h1),
    .R0_clk  (clock),
    .R0_data (_ram_ext_R0_data),
    .W0_addr (enq_ptr_value),
    .W0_en   (do_enq),
    .W0_clk  (clock),
    .W0_data
      ({io_enq_bits_emit, io_enq_bits_finish, io_enq_bits_last, io_enq_bits_context})
  );
  assign io_enq_ready = io_enq_ready_0;
  assign io_deq_valid = ~empty;
  assign io_deq_bits_context = _ram_ext_R0_data[2:0];
  assign io_deq_bits_last = _ram_ext_R0_data[3];
